        "sampleValue": "预计18分钟"
      },
      "calledNumberText": {
        "type": "string",
        "description": "当前已叫到的号码展示文本。",
        "sampleValue": "已叫到0320"
      },
      "alertStatus": {
        "type": "string",
        "description": "叫号风险告警状态，例如已过号或即将过号。",
        "sampleValue": "即将过号"
      }
    },
    "battery": {
      "levelText": {
        "type": "string",
        "description": "手机当前低电量提醒展示文本。",
        "sampleValue": "电量12%"
      }
    },
    "data": {
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "日历复诊日程的索引项唯一标识符。",
              "sampleValue": "calendar-review-1500"
            },
            "title": {
              "type": "string",
              "description": "日历复诊日程标题。",
              "sampleValue": "复诊"
            },
            "dtStart": {
              "type": "string",
              "description": "复诊日程当天开始时间。",
              "sampleValue": "15:00"
            },
            "dtEnd": {
              "type": "string",
              "description": "复诊日程当天结束时间。",
              "sampleValue": "15:30"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": []
}

